using System.Net;
using System.Net.Http.Json;
using Microsoft.EntityFrameworkCore;
using WebApi.Contracts.Common;
using WebApi.Contracts.Releases;
using WebApi.Infrastructure.Persistence.Entities;
using WebApi.Integration.Tests.Support;
using Xunit;
namespace WebApi.Integration.Tests;
public sealed class PipelineRecoveryTests
{
 internal static async Task<HttpResponseMessage> ActionAsync(PipelineScenario s,Guid id,string action,HttpClient? client=null,string? key=null,string? tag=null,bool omitTag=false)
 {client??=s.Creator;var stage=action=="reopen";await using var db=s.Api.Context();var revision=stage?await db.Set<ReleasePipelineRunStage>().Where(x=>x.Id==id).Select(x=>x.Revision).SingleAsync():await db.Set<ReleasePipelineRun>().Where(x=>x.Id==id).Select(x=>x.Revision).SingleAsync();using var request=new HttpRequestMessage(HttpMethod.Post,$"/api/v1/{(stage?"release-pipeline-run-stages":"release-pipeline-runs")}/{id}/{action}"){Content=JsonContent.Create(new PipelineActionRequest("明确办理本次运行操作"))};if(!omitTag)request.Headers.Add("If-Match",tag??RevisionTag.Format(revision));request.Headers.Add("Idempotency-Key",key??Guid.NewGuid().ToString("N"));request.Headers.Add("X-CSRF-Token",(await client.GetFromJsonAsync<Dictionary<string,string>>("/api/v1/auth/csrf"))!["token"]);return await client.SendAsync(request);}
 internal static async Task TimeoutAsync(PipelineScenario s,Guid runId,Guid stageId)
 {await using(var db=s.Api.Context()){var stage=await db.Set<ReleasePipelineRunStage>().SingleAsync(x=>x.Id==stageId);var attempt=await db.Set<ReleasePipelineStageAttempt>().SingleAsync(a=>a.Id==stage.CurrentAttemptId);attempt.Status="TimedOut";stage.Status="TimedOut";(await db.Set<ReleasePipelineRun>().SingleAsync(x=>x.Id==runId)).Status="TimedOut";await db.SaveChangesAsync();}}
 [Fact] public async Task ManualPauseAndResumeKeepTheSameAttemptAndOriginalDeadline()
 {await using var s=new PipelineScenario();await s.InitializeEnvironmentsAsync();var run=await s.StartAsync(await PipelineStageEvidenceTests.VersionAsync(s));var initial=(await s.Creator.GetFromJsonAsync<PipelineRunDto>($"/api/v1/release-pipeline-runs/{run.Id}"))!.Stages[0];using var paused=await ActionAsync(s,run.Id,"pause");Assert.Equal(HttpStatusCode.OK,paused.StatusCode);Assert.Equal("Paused",(await paused.Content.ReadFromJsonAsync<PipelineRunDto>())!.Status);using var resumed=await ActionAsync(s,run.Id,"resume");Assert.Equal(HttpStatusCode.OK,resumed.StatusCode);var view=(await resumed.Content.ReadFromJsonAsync<PipelineRunDto>())!;Assert.Equal("Active",view.Status);Assert.Equal(initial.CurrentAttemptId,view.Stages[0].CurrentAttemptId);Assert.Equal(initial.DeadlineAt,view.Stages[0].DeadlineAt);Assert.Equal("no-store",resumed.Headers.CacheControl!.ToString());}
 [Theory][InlineData("TimedOut")][InlineData("Rejected")][InlineData("DeploymentFailed")][InlineData("VerificationFailed")]
 public async Task FailedWindowsRequireReopenInsteadOfResume(string cause)
 {await using var s=new PipelineScenario();await s.InitializeEnvironmentsAsync();var run=await s.StartAsync(await PipelineStageEvidenceTests.VersionAsync(s));await using(var db=s.Api.Context()){var stage=await db.Set<ReleasePipelineRunStage>().SingleAsync(x=>x.Id==run.Stages[0].Id);stage.Status=cause;(await db.Set<ReleasePipelineStageAttempt>().SingleAsync(x=>x.Id==stage.CurrentAttemptId)).Status=cause;(await db.Set<ReleasePipelineRun>().SingleAsync(x=>x.Id==run.Id)).Status=cause=="TimedOut"?"TimedOut":"Paused";await db.SaveChangesAsync();}using var response=await ActionAsync(s,run.Id,"resume");Assert.Equal(HttpStatusCode.Conflict,response.StatusCode);}
 [Fact] public async Task ReopenSameSourceDeploymentRejectsOldContextAndEarlyEvidence()
 {await using var s=new PipelineScenario();await s.InitializeEnvironmentsAsync();var run=await s.StartAsync(await PipelineStageEvidenceTests.VersionAsync(s));var stage=run.Stages[0];var old=await PipelineStageEvidenceTests.ContextAsync(s.Creator,stage.Id);await TimeoutAsync(s,run.Id,stage.Id);using var response=await ActionAsync(s,stage.Id,"reopen");Assert.True(response.IsSuccessStatusCode,await response.Content.ReadAsStringAsync());var reopened=(await response.Content.ReadFromJsonAsync<PipelineRunStageDto>())!;var current=await PipelineStageEvidenceTests.ContextAsync(s.Creator,stage.Id);Assert.NotEqual(old.CurrentAttemptId,current.CurrentAttemptId);Assert.NotEqual(old.ContextHash,current.ContextHash);Assert.Equal(old.SnapshotHash,current.SnapshotHash);Assert.Equal(old.ReleaseId,current.ReleaseId);Assert.True(reopened.ActivatedAt>stage.ActivatedAt);using var stale=await PipelineStageEvidenceTests.RecordAsync(s.Creator,stage.Id,old);Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);using var early=await PipelineStageEvidenceTests.RecordAsync(s.Creator,stage.Id,current,finished:reopened.ActivatedAt!.Value.AddMilliseconds(-1));Assert.Equal(HttpStatusCode.UnprocessableEntity,early.StatusCode);using var fresh=await PipelineStageEvidenceTests.RecordAsync(s.Creator,stage.Id,current);Assert.Equal(HttpStatusCode.OK,fresh.StatusCode);await using var db=s.Api.Context();var next=await db.Set<ReleasePipelineStageAttempt>().SingleAsync(a=>a.Id==current.CurrentAttemptId);Assert.Equal(2,next.AttemptNo);Assert.Equal(old.CurrentAttemptId,next.OriginAttemptId);Assert.Null(next.AcceptanceId);Assert.Equal("Active",(await db.Set<ReleasePipelineRun>().SingleAsync(r=>r.Id==run.Id)).Status);}
 [Theory][InlineData("missing")][InlineData("stale")]
 public async Task RecoveryRequiresTheActualResourceEtag(string fault)
 {await using var s=new PipelineScenario();await s.InitializeEnvironmentsAsync();var run=await s.StartAsync(await PipelineStageEvidenceTests.VersionAsync(s));using var response=await ActionAsync(s,run.Id,"pause",tag:fault=="stale"?"\"v999\"":null,omitTag:fault=="missing");Assert.Equal(HttpStatusCode.PreconditionFailed,response.StatusCode);}
 [Fact] public async Task ConcurrentReopenCreatesOneActiveAttemptAndReplayIsTheSameReceipt()
 {await using var s=new PipelineScenario();await s.InitializeEnvironmentsAsync();var run=await s.StartAsync(await PipelineStageEvidenceTests.VersionAsync(s));var stage=run.Stages[0];await TimeoutAsync(s,run.Id,stage.Id);string tag;await using(var db=s.Api.Context())tag=RevisionTag.Format((await db.Set<ReleasePipelineRunStage>().SingleAsync(x=>x.Id==stage.Id)).Revision);var key=Guid.NewGuid().ToString("N");var responses=await Task.WhenAll(ActionAsync(s,stage.Id,"reopen",key:key,tag:tag),ActionAsync(s,stage.Id,"reopen",key:key,tag:tag));try{foreach(var response in responses)Assert.True(response.IsSuccessStatusCode,await response.Content.ReadAsStringAsync());Assert.Equal(await responses[0].Content.ReadAsStringAsync(),await responses[1].Content.ReadAsStringAsync());}finally{foreach(var response in responses)response.Dispose();}await using var verify=s.Api.Context();Assert.Equal(2,await verify.Set<ReleasePipelineStageAttempt>().CountAsync(a=>a.RunId==run.Id));Assert.Equal(1,await verify.Set<ReleasePipelineStageAttempt>().CountAsync(a=>a.RunId==run.Id&&a.Status=="Active"));}
 [Fact] public async Task UnemittedCandidateIsCancelledAndNewAttemptRequiresNewMappingAndApproval()
 {await using var f=new PipelinePromotionFixture();await f.InitializeAsync(2);var p=await PipelineExecutionTests.SubmittedAsync(f);await TimeoutAsync(f.Scenario,f.Run.Id,f.TargetStageId);using var reopened=await ActionAsync(f.Scenario,f.TargetStageId,"reopen");Assert.True(reopened.IsSuccessStatusCode,await reopened.Content.ReadAsStringAsync());var stage=(await reopened.Content.ReadFromJsonAsync<PipelineRunStageDto>())!;Assert.Equal("AwaitingMapping",stage.Status);await using(var db=f.Scenario.Api.Context()){Assert.Equal("Cancelled",(await db.Set<ReleasePromotion>().SingleAsync(x=>x.Id==p.Id)).Status);Assert.Equal("Cancelled",(await db.Set<ReleaseRecord>().SingleAsync(x=>x.Id==p.TargetReleaseId)).Status);Assert.Null((await db.Set<ReleasePipelineStageAttempt>().SingleAsync(a=>a.Id==stage.CurrentAttemptId)).PromotionId);Assert.Equal(1L,(await db.Set<EnvironmentRecord>().SingleAsync(e=>e.Id==f.TargetEnvironmentId)).DeploymentSequence);}using var prepared=await f.PrepareAsync();Assert.True(prepared.IsSuccessStatusCode,await prepared.Content.ReadAsStringAsync());var next=(await prepared.Content.ReadFromJsonAsync<PromotionDto>())!;Assert.NotEqual(p.Id,next.Id);Assert.Null(next.Mapping);Assert.Null(next.TargetReleaseId);}
 [Fact] public async Task AlreadyEmittedFailureReopensAnExactSnapshotRetryWithoutRewritingFormalAttempt()
 {await using var f=new PipelinePromotionFixture();await f.InitializeAsync(2);var p=await PipelineExecutionTests.ReadyAsync(f);using(var published=await ApiFixture.CommandAsync(f.Scenario.Creator,$"/api/v1/releases/{p.TargetReleaseId}/publish"))published.EnsureSuccessStatusCode();await f.Scenario.Source.Deployment.BuildQueuedAsync();Guid formal;string hash;byte[] candidate;await using(var db=f.Scenario.Api.Context()){formal=(await db.Set<ReleasePromotion>().SingleAsync(x=>x.Id==p.Id)).StageAttemptId!.Value;var release=await db.Set<ReleaseRecord>().SingleAsync(x=>x.Id==p.TargetReleaseId);candidate=release.CandidateBytes!;hash=(await db.Set<GatewayConfigVersion>().SingleAsync(x=>x.EnvironmentId==f.TargetEnvironmentId&&x.VersionNo==release.ToConfigVersion)).SnapshotHash!;release.Status="Failed";release.FailureCode="activation_timeout";release.CompletedAt=DateTimeOffset.UtcNow;(await db.Set<EnvironmentRecord>().SingleAsync(x=>x.Id==f.Run.SourceEnvironmentId)).DeploymentSequence=999;await db.SaveChangesAsync();}await f.Scenario.ProjectAsync(f.Run.Id);using var reopened=await ActionAsync(f.Scenario,f.TargetStageId,"reopen");Assert.True(reopened.IsSuccessStatusCode,await reopened.Content.ReadAsStringAsync());var stage=(await reopened.Content.ReadFromJsonAsync<PipelineRunStageDto>())!;await using(var db=f.Scenario.Api.Context()){var attempt=await db.Set<ReleasePipelineStageAttempt>().SingleAsync(a=>a.Id==stage.CurrentAttemptId);Assert.NotEqual(formal,attempt.Id);Assert.Equal(formal,attempt.OriginAttemptId);Assert.Null(attempt.PromotionId);var retry=await db.Set<ReleaseRecord>().SingleAsync(r=>r.Id==attempt.ActualReleaseId);Assert.Equal("retry",retry.ReleaseType);Assert.Equal("Building",retry.Status);Assert.Equal(p.TargetReleaseId,retry.RecoveryOf);Assert.Equal(candidate,retry.CandidateBytes);Assert.Equal(formal,(await db.Set<ReleasePromotion>().SingleAsync(x=>x.Id==p.Id)).StageAttemptId);Assert.Equal(1,await db.Set<ReleaseRecord>().CountAsync(r=>r.PromotionId==p.Id));}await f.Scenario.Source.Deployment.BuildQueuedAsync();await using var verify=f.Scenario.Api.Context();var emitted=await verify.Set<ReleaseRecord>().SingleAsync(r=>r.ReleaseType=="retry");Assert.Equal("Publishing",emitted.Status);Assert.Equal(3L,emitted.DeploymentSequence);Assert.Equal(hash,(await verify.Set<GatewayConfigVersion>().SingleAsync(c=>c.EnvironmentId==f.TargetEnvironmentId&&c.VersionNo==emitted.ToConfigVersion)).SnapshotHash);await f.Scenario.AcknowledgeAsync(emitted.Id);await f.Scenario.ProjectAsync(f.Run.Id);var verifier=await PipelineExecutionTests.ApproverAsync(f,"ExactRecoveryVerifier");var context=(await verifier.Client.GetFromJsonAsync<ProductionVerificationContextDto>($"/api/v1/release-promotions/{p.Id}/verification-context"))!;Assert.Equal(stage.CurrentAttemptId,context.StageAttemptId);Assert.Equal(emitted.Id,context.ReleaseId);Assert.Equal(hash,context.SnapshotHash);Assert.Equal(3L,context.DeploymentSequence);await f.Scenario.PassCurrentAsync(f.Run.Id,verifier.Client);await using var final=f.Scenario.Api.Context();Assert.Equal("Completed",(await final.Set<ReleasePipelineRun>().SingleAsync(r=>r.Id==f.Run.Id)).Status);Assert.Equal(formal,(await final.Set<ReleasePromotion>().SingleAsync(x=>x.Id==p.Id)).StageAttemptId);Assert.Equal("Failed",(await final.Set<ReleaseRecord>().SingleAsync(r=>r.Id==p.TargetReleaseId)).Status);}
 [Fact] public async Task PublishingCannotBeReopenedEvenIfItsStageWindowTimedOut()
 {await using var f=new PipelinePromotionFixture();await f.InitializeAsync(2);var p=await PipelineExecutionTests.ReadyAsync(f);using(var published=await ApiFixture.CommandAsync(f.Scenario.Creator,$"/api/v1/releases/{p.TargetReleaseId}/publish"))published.EnsureSuccessStatusCode();await f.Scenario.Source.Deployment.BuildQueuedAsync();await TimeoutAsync(f.Scenario,f.Run.Id,f.TargetStageId);using var response=await ActionAsync(f.Scenario,f.TargetStageId,"reopen");Assert.Equal(HttpStatusCode.Conflict,response.StatusCode);await using var db=f.Scenario.Api.Context();Assert.Equal(2,await db.Set<ReleasePipelineStageAttempt>().CountAsync(a=>a.RunId==f.Run.Id));Assert.Equal("Publishing",(await db.Set<ReleaseRecord>().SingleAsync(r=>r.Id==p.TargetReleaseId)).Status);}
 [Fact] public async Task SucceededProductionReopensVerificationWithNewFloorAndFrozenFormalOrigin()
 {await using var f=new PipelinePromotionFixture();await f.InitializeAsync(2);var p=await PipelineExecutionTests.ReadyAsync(f);await PipelineExecutionTests.SeedSucceededAfterRealBuildAsync(f,p);var verifier=await PipelineExecutionTests.ApproverAsync(f,"PipelineReopenVerifier");var old=(await verifier.Client.GetFromJsonAsync<ProductionVerificationContextDto>($"/api/v1/release-promotions/{p.Id}/verification-context"))!;await TimeoutAsync(f.Scenario,f.Run.Id,f.TargetStageId);using var response=await ActionAsync(f.Scenario,f.TargetStageId,"reopen");Assert.True(response.IsSuccessStatusCode,await response.Content.ReadAsStringAsync());var stage=(await response.Content.ReadFromJsonAsync<PipelineRunStageDto>())!;var current=(await verifier.Client.GetFromJsonAsync<ProductionVerificationContextDto>($"/api/v1/release-promotions/{p.Id}/verification-context"))!;Assert.NotEqual(old.Hash,current.Hash);Assert.NotEqual(old.StageAttemptId,current.StageAttemptId);Assert.Equal(old.ReleaseId,current.ReleaseId);Assert.Equal(old.SnapshotHash,current.SnapshotHash);using var stale=await ApiFixture.CommandAsync(verifier.Client,$"/api/v1/release-promotions/{p.Id}/verifications",new RecordVerificationRequest("EntryConnectivity","Passed",DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,ExpectedContextHash:old.Hash));Assert.Equal(HttpStatusCode.Conflict,stale.StatusCode);using var early=await ApiFixture.CommandAsync(verifier.Client,$"/api/v1/release-promotions/{p.Id}/verifications",new RecordVerificationRequest("EntryConnectivity","Passed",stage.ActivatedAt!.Value.AddMilliseconds(-1),stage.ActivatedAt.Value.AddMilliseconds(-1),ExpectedContextHash:current.Hash));Assert.Equal(HttpStatusCode.UnprocessableEntity,early.StatusCode);}
 [Theory][InlineData("Completed")][InlineData("Cancelled")][InlineData("Invalidated")]
 public async Task TerminalRunsCannotResumeOrReopen(string state)
 {await using var s=new PipelineScenario();await s.InitializeEnvironmentsAsync();var run=await s.StartAsync(await PipelineStageEvidenceTests.VersionAsync(s));await using(var db=s.Api.Context()){(await db.Set<ReleasePipelineRun>().SingleAsync(r=>r.Id==run.Id)).Status=state;await db.SaveChangesAsync();}using var resume=await ActionAsync(s,run.Id,"resume");Assert.Equal(HttpStatusCode.Conflict,resume.StatusCode);using var reopen=await ActionAsync(s,run.Stages[0].Id,"reopen");Assert.Equal(HttpStatusCode.Conflict,reopen.StatusCode);}
 [Theory][InlineData(false)][InlineData(true)]
 public async Task CancelStopsQueuedWorkAndPreservesAppliedWorkWithoutRollback(bool emitted)
 {await using var f=new PipelinePromotionFixture();await f.InitializeAsync(2);var p=await PipelineExecutionTests.ReadyAsync(f);using(var published=await ApiFixture.CommandAsync(f.Scenario.Creator,$"/api/v1/releases/{p.TargetReleaseId}/publish"))published.EnsureSuccessStatusCode();if(emitted)await f.Scenario.Source.Deployment.BuildQueuedAsync();using var cancelled=await ActionAsync(f.Scenario,f.Run.Id,"cancel");Assert.True(cancelled.IsSuccessStatusCode,await cancelled.Content.ReadAsStringAsync());Assert.Equal("Cancelled",(await cancelled.Content.ReadFromJsonAsync<PipelineRunDto>())!.Status);await using var db=f.Scenario.Api.Context();Assert.Equal(emitted?"Publishing":"Cancelled",(await db.Set<ReleaseRecord>().SingleAsync(r=>r.Id==p.TargetReleaseId)).Status);Assert.Equal(emitted?2L:1L,(await db.Set<EnvironmentRecord>().SingleAsync(e=>e.Id==f.TargetEnvironmentId)).DeploymentSequence);Assert.False(await db.Set<ReleaseRecord>().AnyAsync(r=>r.ReleaseType=="rollback"));Assert.Equal("Passed",(await db.Set<ReleasePipelineRunStage>().SingleAsync(s=>s.Id==f.Run.Stages[0].Id)).Status);}
 [Fact] public async Task CurrentStageDelegateReopensWithDirectSourceReadAndTargetWriteOnly()
 {await using var f=new PipelinePromotionFixture();await f.InitializeAsync(4);await TimeoutAsync(f.Scenario,f.Run.Id,f.TargetStageId);var user=await PipelineExecutionTests.ActorAsync(f);await using(var db=f.Scenario.Api.Context()){await db.Set<UserProjectScope>().Where(s=>s.UserId==user.User.Id).ExecuteDeleteAsync();db.Add(new UserProjectScope{UserId=user.User.Id,OrganizationId=f.Scenario.Api.Organization.Id,ProjectId=f.Run.ProjectId,EnvironmentId=f.Run.SourceEnvironmentId,AccessMode="read_only"});db.Add(new UserProjectScope{UserId=user.User.Id,OrganizationId=f.Scenario.Api.Organization.Id,ProjectId=f.Run.ProjectId,EnvironmentId=f.TargetEnvironmentId,AccessMode="read_write"});await db.SaveChangesAsync();}using var response=await ActionAsync(f.Scenario,f.TargetStageId,"reopen",user.Client);Assert.True(response.IsSuccessStatusCode,await response.Content.ReadAsStringAsync());}
 [Fact] public async Task RunActionCannotUseOnlyOneEnvironmentWriteScope()
 {await using var f=new PipelinePromotionFixture();await f.InitializeAsync(2);var user=await PipelineExecutionTests.ActorAsync(f);await f.Scenario.GrantAsync(user.User.Id,"project.write");await using(var db=f.Scenario.Api.Context()){await db.Set<UserProjectScope>().Where(s=>s.UserId==user.User.Id).ExecuteDeleteAsync();foreach(var env in f.Scenario.Environments)db.Add(new UserProjectScope{UserId=user.User.Id,OrganizationId=f.Scenario.Api.Organization.Id,ProjectId=f.Run.ProjectId,EnvironmentId=env,AccessMode=env==f.TargetEnvironmentId?"read_write":"read_only"});await db.SaveChangesAsync();}using var response=await ActionAsync(f.Scenario,f.Run.Id,"pause",user.Client);Assert.Equal(HttpStatusCode.Forbidden,response.StatusCode);}
 [Fact] public async Task ReopenStillRequiresAdvancementPermissionBeforeReplay()
 {await using var s=new PipelineScenario();await s.InitializeEnvironmentsAsync();var run=await s.StartAsync(await PipelineStageEvidenceTests.VersionAsync(s));await TimeoutAsync(s,run.Id,run.Stages[0].Id);var user=await PipelineStageEvidenceTests.DelegateAsync(s);await using(var db=s.Api.Context()){var role=await db.Set<UserRole>().Where(r=>r.UserId==user.User.Id).Select(r=>r.RoleId).SingleAsync();var permission=await db.Set<Permission>().SingleAsync(p=>p.Code=="pipeline.run");await db.Set<RolePermission>().Where(r=>r.RoleId==role&&r.PermissionId==permission.Id).ExecuteDeleteAsync();}using var response=await ActionAsync(s,run.Stages[0].Id,"reopen",user.Client);Assert.Equal(HttpStatusCode.Forbidden,response.StatusCode);}
 [Fact] public async Task FreshEvidenceAndIndependentAcceptanceAreRequiredInNewSourceWindow()
 {await using var s=new PipelineScenario();await s.InitializeEnvironmentsAsync();var (run,acceptance)=await PipelineProjectionTests.AcceptSourceAsync(s);await TimeoutAsync(s,run.Id,run.Stages[0].Id);using(var response=await ActionAsync(s,run.Stages[0].Id,"reopen"))response.EnsureSuccessStatusCode();await s.ProjectAsync(run.Id);await using(var db=s.Api.Context()){Assert.Equal(1,(await db.Set<ReleasePipelineRun>().SingleAsync(r=>r.Id==run.Id)).CurrentStageOrder);Assert.Equal("Accepted",(await db.Set<ReleaseTestAcceptance>().SingleAsync(a=>a.Id==acceptance)).Status);}var acceptor=await PipelineStageEvidenceTests.DelegateAsync(s);await s.PassSourceAsync(run.Id,s.Creator,acceptor.Client);await using var verify=s.Api.Context();Assert.Equal(2,(await verify.Set<ReleasePipelineRun>().SingleAsync(r=>r.Id==run.Id)).CurrentStageOrder);Assert.Equal(2,await verify.Set<ReleaseTestAcceptance>().CountAsync(a=>a.PipelineRunStageId==run.Stages[0].Id));}
 [Fact] public async Task ManualPauseWithExpiredWindowCannotResume()
 {await using var s=new PipelineScenario();await s.InitializeEnvironmentsAsync();var run=await s.StartAsync(await PipelineStageEvidenceTests.VersionAsync(s));using(var paused=await ActionAsync(s,run.Id,"pause"))paused.EnsureSuccessStatusCode();await using(var db=s.Api.Context()){var attempt=await db.Set<ReleasePipelineStageAttempt>().SingleAsync(a=>a.RunId==run.Id);attempt.ActivatedAt=DateTimeOffset.UtcNow.AddHours(-1);attempt.DeadlineAt=DateTimeOffset.UtcNow.AddMinutes(-1);await db.SaveChangesAsync();}using var response=await ActionAsync(s,run.Id,"resume");Assert.Equal(HttpStatusCode.Conflict,response.StatusCode);}
 [Fact] public async Task FutureAndOrdinaryActiveStagesCannotReopen()
 {await using var s=new PipelineScenario();await s.InitializeEnvironmentsAsync(4);var run=await s.StartAsync(await PipelineStageEvidenceTests.VersionAsync(s));using var active=await ActionAsync(s,run.Stages[0].Id,"reopen");Assert.Equal(HttpStatusCode.Conflict,active.StatusCode);using var future=await ActionAsync(s,run.Stages[2].Id,"reopen");Assert.Equal(HttpStatusCode.Conflict,future.StatusCode);}
 [Fact] public async Task PausedQueuedBuildFailureNeedsReopenAndCannotResumeAsAValidManualPause()
 {await using var f=new PipelinePromotionFixture();await f.InitializeAsync(2);var p=await PipelineExecutionTests.ReadyAsync(f);using(var published=await ApiFixture.CommandAsync(f.Scenario.Creator,$"/api/v1/releases/{p.TargetReleaseId}/publish"))published.EnsureSuccessStatusCode();using(var paused=await ActionAsync(f.Scenario,f.Run.Id,"pause"))paused.EnsureSuccessStatusCode();await f.Scenario.Source.Deployment.BuildQueuedAsync();using var resumed=await ActionAsync(f.Scenario,f.Run.Id,"resume");Assert.Equal(HttpStatusCode.Conflict,resumed.StatusCode);using var reopened=await ActionAsync(f.Scenario,f.TargetStageId,"reopen");Assert.True(reopened.IsSuccessStatusCode,await reopened.Content.ReadAsStringAsync());Assert.Equal("AwaitingMapping",(await reopened.Content.ReadFromJsonAsync<PipelineRunStageDto>())!.Status);await using var db=f.Scenario.Api.Context();Assert.Equal(1L,(await db.Set<EnvironmentRecord>().SingleAsync(e=>e.Id==f.TargetEnvironmentId)).DeploymentSequence);}
 [Fact] public async Task ChangedRootBehaviorInvalidatesRunInsteadOfForceReopening()
 {await using var s=new PipelineScenario();await s.InitializeEnvironmentsAsync();var run=await s.StartAsync(await PipelineStageEvidenceTests.VersionAsync(s));await TimeoutAsync(s,run.Id,run.Stages[0].Id);await s.Source.Deployment.PublishAsync();using var reopened=await ActionAsync(s,run.Stages[0].Id,"reopen");Assert.Equal(HttpStatusCode.Conflict,reopened.StatusCode);await using var db=s.Api.Context();Assert.Equal("Invalidated",(await db.Set<ReleasePipelineRun>().SingleAsync(r=>r.Id==run.Id)).Status);Assert.Equal(1,await db.Set<ReleasePipelineStageAttempt>().CountAsync(a=>a.RunId==run.Id));}

